def day_to_num(s):
    if s[0] == 'm':
        return 1
    elif s[0] == 't' and s[1] == 'u':
        return 2
    elif s[0] == 'w':
        return 3
    elif s[0] == 't' and s[1] == 'h':
        return 4
    elif s[0] == 'f':
        return 5
    elif s[0] == 's' and s[1] == 'a':
        return 6
    elif s[0] == 's' and s[1] == 'u':
        return 7

def main():
    s, s1 = input().split()
    a = day_to_num(s)
    b = day_to_num(s1)
    k = a - b
    l = b - a
    if l == 0 or l == 2 or l == 3 or k == 4 or k == 5:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()

